name: PR Preview Deployment

on:
  pull_request:
    paths:
      - 'website/**'
  workflow_dispatch:

permissions:
  contents: read
  pull-requests: write

jobs:
  preview:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Setup .NET
        uses: actions/setup-dotnet@v4
        with:
          dotnet-version: '6.x'

      - name: Restore dependencies
        run: dotnet restore

      - name: Build website
        run: dotnet publish -c Release -o website/publish

      - name: Upload preview artifact
        uses: actions/upload-artifact@v4
        with:
          name: website-preview
          path: website/publish
          retention-days: 30

      - name: Deploy to Cloudflare Pages
        id: cloudflare
        if: secrets.CLOUDFLARE_API_TOKEN && secrets.CLOUDFLARE_ACCOUNT_ID
        uses: cloudflare/wrangler-action@v3
        with:
          apiToken: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          accountId: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          command: pages deploy
          workingDirectory: website/publish
          environment: preview
          quiet: true

      - name: Post preview comment
        if: github.event_name == 'pull_request'
        uses: actions/github-script@v6
        env:
          ARTIFACT_URL: https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}
          CLOUDFLARE_URL: ${{ steps.cloudflare.outputs.pages-deployment-alias-url }}
        with:
          script: |
            const marker = '<!-- preview-deployment -->';
            const prNumber = context.payload.pull_request.number;
            const artifactLink = `**Artifact**: [Download](${process.env.ARTIFACT_URL})`;
            const previewLink = process.env.CLOUDFLARE_URL ? `**Live Preview**: [Open](${process.env.CLOUDFLARE_URL})` : '';
            const body = `${marker}\n\n${previewLink}\n\n${artifactLink}`;
            const comments = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber
            });
            const existing = comments.data.find(c => c.body.includes(marker));
            if (existing) {
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: existing.id,
                body: body
              });
            } else {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: body
              });
            }
